sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_spacing;
uniform float amzp_ballSize;
uniform float amzp_alphaThr;
uniform float amzp_scatter;
uniform float amzp_depthScat;
uniform float amzp_instab;
uniform float amzp_rotAxis;
uniform float amzp_rotation;
uniform float amzp_twistProp;
uniform float amzp_twist;
uniform float amzp_seed;
uniform float amzp_persp;
uniform float amzp_lightAngle;
uniform float amzp_lightInt;
uniform float amzp_ambient;
uniform float amzp_specular;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float3 h33(float2 p) {
        float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973) + amzp_seed * 0.0173);
        q += dot(q, q.yxz + 33.33);
        return fract((q.xxy + q.yzz) * q.zyx);
    }
    float3 rotA(float3 v, float3 k, float a) {
        float c = cos(a), s = sin(a);
        return v * c + cross(k, v) * s + k * dot(k, v) * (1.0 - c);
    }
    float3 axisK() {
        if (int(amzp_rotAxis) == 0) return float3(1.0, 0.0, 0.0);
        if (int(amzp_rotAxis) == 1) return float3(0.0, 1.0, 0.0);
        if (int(amzp_rotAxis) == 2) return float3(0.0, 0.0, 1.0);
        if (int(amzp_rotAxis) == 3) return normalize(float3(1.0, 1.0, 0.0));
        if (int(amzp_rotAxis) == 4) return normalize(float3(1.0, 0.0, 1.0));
        if (int(amzp_rotAxis) == 5) return normalize(float3(0.0, 1.0, 1.0));
        return normalize(float3(1.0));
    }
    float2 W; float S; float2 NC; float3 K; float ANG; float TW; float RB; float SC;
    float twW(float2 c0) {
        if (int(amzp_twistProp) == 0) return length(c0) / max(0.5 * length(W), 1.0);
        if (int(amzp_twistProp) == 1) return c0.x / max(W.x, 1.0) + 0.5;
        return c0.y / max(W.y, 1.0) + 0.5;
    }
    float2 cellCenter(float2 cell) { return (cell + 0.5) * S - 0.5 * W; }
    float h21(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 17.13) * 43758.5453123); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), f.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float2 sField(float2 c0) {
        float ia = radians(amzp_instab);
        float2 p = c0 / max(S * 7.0, SC * 2.0) + float2(cos(ia), sin(ia)) * 0.8 + float2(ia * 0.05, 0.0);
        return float2(vn(p), vn(p + float2(17.3, 5.1))) * 2.0 - 1.0;
    }
    float radK() { return SC * 0.6 / max(0.5 * length(W), 1.0); }
    float2 sOff(float2 c0) { return (sField(c0) - sField(float2(0.0))) * SC * 0.6; }
    float3 ballPos(float2 cell, float2 c0) {
        float3 p = rotA(float3(c0 * (1.0 + radK()), 0.0), K, ANG + TW * twW(c0));
        if (SC > 0.0) {
            float3 r = h33(cell) - 0.5;
            if (amzp_instab != 0.0) {
                float3 ax = normalize(h33(cell + 71.3) - 0.5 + float3(1e-4));
                r = rotA(r, ax, radians(amzp_instab));
            }
            float2 jit = r.xy * 2.0 * min(SC, S * 1.1);
            p += float3(sOff(c0) + jit, r.z * amzp_depthScat * 2.0 * SC);
        }
        return p;
    }
    void amzRender() {
        W = layer;
        S = max(amzp_spacing * pxs(), 1.0);
        NC = ceil(W / S);
        K = axisK();
        ANG = radians(amzp_rotation);
        TW = radians(amzp_twist);
        RB = 0.5 * S * max(amzp_ballSize, 0.01);
        SC = amzp_scatter * pxs();
        float2 P = (amzLayerNorm() - 0.5) * W;
        float D = 2.0 * max(W.x, W.y) / max(amzp_persp, 0.05);
        float3 O = float3(0.0, 0.0, D);
        float3 dr = normalize(float3(P, -D));
        float q = floor(clamp(amzp_quality, 1.0, 4.0) + 0.5);
        float Mmax = q < 1.5 ? 4.0 : (q < 2.5 ? 8.0 : (q < 3.5 ? 12.0 : 16.0));
        float Kmax = q < 1.5 ? 2.0 : 3.0;
        float KW = SC > 0.0 ? Kmax : 1.0;
        float Rg = 0.5 * length(W) + SC * 2.0 + RB * 2.0;
        float b = dot(O, dr);
        float disc = b * b - (dot(O, O) - Rg * Rg);
        float4 R = float4(0.0);
        if (disc > 0.0) {
            float sq = sqrt(disc);
            float t0 = max(-b - sq, 0.0), t1 = -b + sq;
            float3 n = rotA(float3(0.0, 0.0, 1.0), K, ANG);
            float dn = dot(dr, n), on = dot(O, n);
            float hth = RB + SC * 2.0 * max(amzp_depthScat, 0.0);
            if (abs(dn) > 1e-4 && TW == 0.0) {
                float ta = (-hth - on) / dn, tb = (hth - on) / dn;
                t0 = max(t0, min(ta, tb)); t1 = min(t1, max(ta, tb));
            }
            if (t1 > t0) {
                float segL = (t1 - t0) * sqrt(max(1.0 - dn * dn, 0.0));
                float M = clamp(ceil(segL / S) + 1.0, 1.0, Mmax);
                float bestT = 1e9;
                float3 bestC = float3(0.0); float4 bestCol = float4(0.0); float bestD = 0.0;
                for (int k = 0; k < 16; k++) {
                    float fk = float(k);
                    if (fk >= M) break;
                    float tk = M > 1.0 ? mix(t0, t1, fk / (M - 1.0)) : 0.5 * (t0 + t1);
                    if (tk > bestT + RB * 2.0) break;
                    float3 X = O + dr * tk;
                    float a = ANG;
                    float3 g = rotA(X, K, -a);
                    if (TW != 0.0 || SC > 0.0) {
                        for (int it = 0; it < 3; it++) {
                            float2 gc = cellCenter(floor(g.xy / S + 0.5 * W / S));
                            float3 so = SC > 0.0 ? float3(sOff(gc), 0.0) : float3(0.0);
                            a = ANG + TW * twW(g.xy);
                            g = rotA(X - so, K, -a);
                            g.xy /= 1.0 + radK();
                        }
                    }
                    float2 cc = floor(g.xy / S + 0.5 * W / S);
                    for (int dy = -3; dy <= 3; dy++) {
                        for (int dx = -3; dx <= 3; dx++) {
                            if (abs(float(dx)) > KW || abs(float(dy)) > KW) continue;
                            float2 cell = cc + float2(float(dx), float(dy));
                            if (cell.x < 0.0 || cell.y < 0.0 || cell.x >= NC.x || cell.y >= NC.y) continue;
                            float2 c0 = cellCenter(cell);
                            float4 col = layerAt(c0 / W + 0.5);
                            if (col.a < max(amzp_alphaThr, 0.001)) continue;
                            float3 C = ballPos(cell, c0);
                            float3 oc = O - C;
                            float bb = dot(oc, dr);
                            float cq = dot(oc, oc) - RB * RB;
                            float h = bb * bb - cq;
                            float dist = sqrt(max(dot(oc, oc) - bb * bb, 0.0));
                            float aaR = RB + 1.0;
                            if (dist > aaR) continue;
                            float th = h > 0.0 ? -bb - sqrt(h) : -bb;
                            if (th > 0.0 && th < bestT) { bestT = th; bestC = C; bestCol = col; bestD = dist; }
                        }
                    }
                }
                if (bestT < 1e8) {
                    float3 hp = O + dr * bestT;
                    float3 N = normalize(hp - bestC);
                    if (bestD >= RB) N = normalize(float3(normalize((hp - bestC).xy + 1e-5), 0.0));
                    float la = radians(amzp_lightAngle);
                    float3 L = normalize(float3(cos(la), sin(la), 1.2));
                    float3 V = -dr;
                    float dif = max(dot(N, L), 0.0);
                    float sp = pow(max(dot(reflect(-L, N), V), 0.0), 24.0);
                    float3 base = bestCol.rgb / max(bestCol.a, 0.0001);
                    float3 c = base * (amzp_ambient + amzp_lightInt * dif) + float3(sp * amzp_specular);
                    float cov = 1.0 - smoothstep(RB - 1.0, RB + 0.5, bestD);
                    float al = bestCol.a * cov;
                    R = float4(clamp(c, 0.0, 1.0) * al, al);
                }
            }
        }
        amzOutput = R;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
